import { BrowserRouter, Routes, Route, Link } from 'react-router-dom';

export default function App() {
  return (
    <BrowserRouter>
      <nav>
        <Link to="/">Каталог</Link>
        <Link to="/clients">Клиенты</Link>
        <Link to="/planner">Планировщик</Link>
      </nav>
      <Routes>
        <Route path="/" element={<div>Каталог процедур</div>} />
        <Route path="/clients" element={<div>Список клиентов</div>} />
        <Route path="/planner" element={<div>Планировщик курса</div>} />
      </Routes>
    </BrowserRouter>
  );
}
